<template>
  <main class="club-form-page"><header class="topbar"><router-link :to="route.params.id ? '/clubs/' + route.params.id + '/public' : '/clubs'" aria-label="返回跑团">‹</router-link><h1>{{ route.params.id ? '名称与身份反馈' : '我的身份反馈与申诉' }}</h1><span></span></header>
    <div class="club-form-wrap"><p class="club-form-eyebrow">CLEAR IDENTITY, FAIR COMMUNITY</p><h2 class="club-form-title">把事实说清，让跑友认准。</h2><p class="club-form-lead">同名跑团可以并存。若出现冒充组织、误导招募或管理授权争议，可以请平台私密核对。</p>
      <div v-if="!token" class="club-form-panel"><p class="club-form-hint">登录后可提交反馈、补充说明并查看处理进度，无需加入对方跑团。</p><button class="club-form-primary" type="button" @click="login">登录并继续</button></div>
      <p v-if="loading" class="club-form-hint" role="status">正在读取资料…</p><p v-if="error" class="club-form-error" role="alert">{{ error }}<button v-if="!saving" type="button" @click="load">重新读取</button></p>
      <form v-if="token && route.params.id && club" class="club-form-panel" @submit.prevent="submit"><span class="club-private-tag">私密工单 · 不会公开联系方式或材料</span><h2>{{ club.name }}</h2><p class="club-form-hint">{{ club.city || '城市待补充' }} · 负责人 {{ club.leader || '待补充' }} · 团号 #{{ club.id }}</p>
        <p v-if="editingReportId" class="club-form-note">正在更新工单 #{{ editingReportId }}。本次提交会保存为该工单的最新说明、公共来源和联系方式，请保留仍需平台核对的原有事实。</p><label><span>需要核对的情况</span><select v-model="form.type" aria-label="需要核对的情况" :disabled="saving || !!editingReportId"><option v-for="(label, value) in reportTypes" :key="value" :value="value">{{ label }}</option></select></label>
        <p class="club-form-note">{{ form.type === 'confusion' ? '仅有同名不会默认处罚。可以建议补充城市、简介与团号，帮助跑友区分。' : form.type === 'management' ? '请说明授权关系与可核对的组织记录。平台核对事实，申诉不会自动转移成员、会费、活动或账号控制权。' : '请指出具体误导位置、所声称的组织授权，以及可核对的来源。一条举报不会自动下架对方跑团。' }}</p>
        <label><span>{{ form.type === 'confusion' ? '区分建议与具体情况' : '具体事实与可核对材料' }} <small>必填</small></span><textarea v-model="form.detail" aria-label="具体事实与可核对材料" rows="6" maxlength="4000" required :disabled="saving" placeholder="说明你与组织的关系、需要核对的具体表述，以及已有材料或本次补充内容。请勿提交无关个人资料。" /></label>
        <label><span>相关公共来源 <small>选填</small></span><input v-model="form.sourceUrl" aria-label="相关公共来源" type="url" maxlength="1000" :disabled="saving" placeholder="可核对组织关系的公共页面链接" /></label>
        <label><span>私密联系方式 <small>仅处理人员可见</small></span><input v-model="form.contact" aria-label="私密联系方式" maxlength="200" required :disabled="saving" placeholder="便于平台核对和联系" /></label>
        <p v-if="notice" class="club-form-success" role="status">{{ notice }}</p><button class="club-form-primary" type="submit" :disabled="saving">{{ saving ? '正在提交…' : editingReportId ? '保存工单更新' : '私密提交反馈' }}</button><button v-if="editingReportId" class="club-form-link" type="button" :disabled="saving" @click="cancelEdit">取消更新</button>
      </form>
      <section v-if="token" class="reports-progress"><h2>我的处理进度 <button type="button" @click="load" :disabled="loading || saving">刷新</button></h2><p v-if="!loading && !reports.length" class="club-form-hint">你还没有提交过名称或身份反馈。</p><article v-for="report in reports" :key="report.id" class="club-record"><span class="club-record-status">{{ reportStatuses[report.status] || report.status || '待处理' }}</span><h3>{{ report.clubName }} · #{{ report.clubId }}</h3><p>{{ reportTypes[report.type] || report.type }} · 工单 #{{ report.id }} · {{ identityDate(report.createdAt) }}</p><p>{{ report.detail }}</p><p v-if="report.note"><strong>处理回复</strong><br>{{ report.note }}</p><a v-if="safeSource(report.sourceUrl)" class="club-form-link" :href="safeSource(report.sourceUrl)" target="_blank" rel="noopener noreferrer">查看你提交的公共来源 ↗</a><button v-if="['pending', 'supplement'].includes(report.status)" class="club-form-link" type="button" :disabled="saving" @click="editReport(report)">{{ report.status === 'pending' ? '更新说明与联系方式' : '补充说明' }} →</button><router-link v-else-if="report.status === 'restricted'" class="club-form-link" :to="'/clubs/' + report.clubId + '/report?type=' + report.type">补充说明 / 申请复核 →</router-link></article></section>
    </div>
  </main>
</template>
<script setup>
import { reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useClubSession } from '../useClubSession';
import { identityDate, reportStatuses, reportTypes, safeSource } from '../club-identity';
import '../club-forms.css';
const route = useRoute(), router = useRouter(), club = ref(null), reports = ref([]), loading = ref(false), saving = ref(false), error = ref(''), notice = ref('');
const blank = () => ({ type: Object.hasOwn(reportTypes, route.query.type) ? route.query.type : 'impersonation', detail: '', sourceUrl: '', contact: '' });
const form = reactive(blank());
const editingReportId = ref(null);
function reset() { club.value = null; reports.value = []; editingReportId.value = null; loading.value = false; saving.value = false; error.value = ''; notice.value = ''; Object.assign(form, blank()); }
const { token, capture, current, request } = useClubSession(reset, () => route.fullPath);
function login() { localStorage.setItem('marathon_return_after_login', route.fullPath); router.push('/mine'); }
async function load(prefill = true) { if (!token.value) return; const stamp = capture(); loading.value = true; error.value = ''; try { const result = await Promise.all([request('/me/club-reports'), ...(route.params.id ? [request('/clubs/' + route.params.id + '/public')] : [])]); if (!current(stamp)) return; reports.value = result[0].reports || []; club.value = result[1]?.club || null; if (prefill !== false && route.query.report) { const own = reports.value.find(report => String(report.id) === route.query.report && String(report.clubId) === String(route.params.id) && ['pending', 'supplement'].includes(report.status)); if (own) { editingReportId.value = own.id; Object.assign(form, { type: own.type, detail: own.detail || '', sourceUrl: own.sourceUrl || '', contact: own.contact || '' }); } } } catch (err) { if (!err.stale && current(stamp)) error.value = err.message; } finally { if (current(stamp)) loading.value = false; } }
function editReport(report) { if (saving.value) return; const stamp = capture(); if (!current(stamp)) return; const own = reports.value.find(item => item.id === report.id && ['pending', 'supplement'].includes(item.status)); if (!own) return; if (String(own.clubId) !== String(route.params.id)) { router.push({ path: '/clubs/' + own.clubId + '/report', query: { type: own.type, report: String(own.id) } }); return; } editingReportId.value = own.id; Object.assign(form, { type: own.type, detail: own.detail || '', sourceUrl: own.sourceUrl || '', contact: own.contact || '' }); notice.value = ''; error.value = ''; }
function cancelEdit() { if (saving.value) return; editingReportId.value = null; Object.assign(form, blank()); notice.value = ''; error.value = ''; if (route.query.report) router.replace({ path: route.path, query: { type: form.type } }); }
async function submit() { if (saving.value || !club.value) return; const stamp = capture(); if (!current(stamp)) return; saving.value = true; error.value = ''; notice.value = ''; try { const data = await request('/clubs/' + route.params.id + '/reports', { method: 'POST', body: JSON.stringify(form) }); if (!current(stamp)) return; notice.value = data.outcome === 'updated' ? `工单 #${data.report.id} 的说明、公共来源和联系方式已更新，已进入待处理。` : data.outcome === 'unchanged' ? `工单 #${data.report.id} 已收到相同内容，无需重复提交。处理进度可在下方查看。` : `反馈已私密提交，工单 #${data.report.id}。处理结果会显示在下方。`; editingReportId.value = null; form.detail = ''; form.sourceUrl = ''; form.contact = ''; await load(false); } catch (err) { if (!err.stale && current(stamp)) error.value = err.message; } finally { if (current(stamp)) saving.value = false; } }
watch(() => [token.value, route.fullPath], () => { reset(); load(); }, { immediate: true });
</script>
<style scoped>.reports-progress{margin-top:28px}.reports-progress>h2{display:flex;justify-content:space-between;align-items:center;font-size:17px}.reports-progress>h2 button{min-height:44px;color:#a77e8c;font-size:12px}.club-form-panel h2{margin-top:14px;overflow-wrap:anywhere}.club-record h3{margin-top:13px}.club-record .club-form-link{margin-right:12px}</style>
